#!/usr/bin/env node
'use strict';

// Generates the Web event constants from the normative AsyncAPI document. The browser client
// uses these values for channel names, envelope validation, and protocol version checks.

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const YAML = require('yaml');

const BANNER = [
  '/**',
  ' * Generated by tools/spec/generate-web-events.cjs. Do not edit by hand.',
  ' * Source: specification/api/asyncapi.yaml',
  ' * Regenerate with: npm run generate:web-client --prefix tools/spec',
  ' */',
];

function fail(message) {
  throw new Error(message);
}

function literal(value) {
  return JSON.stringify(value);
}

function readSpec(specPath) {
  const source = fs.readFileSync(specPath, 'utf8');
  const document = YAML.parse(source);
  if (document === null || typeof document !== 'object' || Array.isArray(document)) {
    fail(`${specPath} must contain an AsyncAPI mapping`);
  }
  if (document.asyncapi !== '3.1.0') {
    fail(`unsupported AsyncAPI version: ${String(document.asyncapi)}`);
  }
  return {
    document,
    sha256: crypto.createHash('sha256').update(source, 'utf8').digest('hex'),
  };
}

function messageName(document, reference) {
  const target =
    reference !== null && typeof reference === 'object' && typeof reference.$ref === 'string'
      ? reference.$ref
      : reference;
  if (typeof target !== 'string') {
    fail(`unsupported message reference: ${String(target)}`);
  }
  const channelPrefix = '#/channels/events/messages/';
  if (target.startsWith(channelPrefix)) {
    const name = target.slice(channelPrefix.length);
    const channelMessages = document.channels?.events?.messages;
    const channelMessage = channelMessages === undefined ? undefined : channelMessages[name];
    if (channelMessage === undefined) {
      fail(`unresolved channel message reference: ${target}`);
    }
    return messageName(document, channelMessage);
  }
  const componentPrefix = '#/components/messages/';
  if (!target.startsWith(componentPrefix)) {
    fail(`unsupported message reference: ${target}`);
  }
  return target.slice(componentPrefix.length);
}

function resolveSchema(document, schema) {
  if (schema === null || typeof schema !== 'object' || typeof schema.$ref !== 'string') {
    return schema;
  }
  const prefix = '#/components/schemas/';
  if (!schema.$ref.startsWith(prefix)) {
    fail(`unsupported schema reference: ${String(schema.$ref)}`);
  }
  const name = schema.$ref.slice(prefix.length);
  const schemas = document.components === undefined ? undefined : document.components.schemas;
  if (schemas === undefined || schemas[name] === undefined) {
    fail(`unresolved schema reference: ${String(schema.$ref)}`);
  }
  return schemas[name];
}

function schemaParts(document, schema) {
  const resolved = resolveSchema(document, schema);
  if (resolved === null || typeof resolved !== 'object') {
    return [];
  }
  return Array.isArray(resolved.allOf)
    ? resolved.allOf.map((part) => resolveSchema(document, part))
    : [resolved];
}

function constantFromSchema(document, schema, property, label) {
  for (const part of schemaParts(document, schema)) {
    const properties = part === null || typeof part !== 'object' ? undefined : part.properties;
    const candidate = properties === undefined ? undefined : properties[property];
    if (candidate !== null && typeof candidate === 'object' && typeof candidate.const === 'string') {
      return candidate.const;
    }
  }
  return fail(`missing ${property} constant in ${label}`);
}

function channels(document) {
  const messages = document.components === undefined ? undefined : document.components.messages;
  const subscribe = messages === undefined ? undefined : messages.Subscribe;
  if (subscribe === undefined) {
    fail('Subscribe message is missing from the specification');
  }
  for (const part of schemaParts(document, subscribe.payload)) {
    const channelsSchema = part === null || typeof part !== 'object' ? undefined : part.properties?.channels;
    const items = channelsSchema === undefined ? undefined : channelsSchema.items;
    if (items !== null && typeof items === 'object' && Array.isArray(items.enum)) {
      return items.enum;
    }
  }
  return fail('Subscribe channel enum is missing from the specification');
}

function serverEventTypes(document) {
  const receive = document.operations?.receiveEvents;
  const refs = receive === undefined ? [] : (Array.isArray(receive.messages) ? receive.messages : []);
  if (refs.length === 0) {
    fail('receiveEvents has no server messages');
  }
  const messages = document.components === undefined ? undefined : document.components.messages;
  return refs.map((reference) => {
    const name = messageName(document, reference);
    const message = messages === undefined ? undefined : messages[name];
    if (message === undefined) {
      fail(`unresolved message reference: ${String(reference)}`);
    }
    return constantFromSchema(document, message.payload, 'type', name);
  });
}

function generate(specPath) {
  const { document, sha256 } = readSpec(specPath);
  const address = document.channels?.events?.address;
  if (typeof address !== 'string' || address === '') {
    fail('events channel address is missing from the specification');
  }
  const envelope = document.components?.schemas?.EnvelopeBase;
  const protocolVersion = constantFromSchema(document, envelope, 'protocolVersion', 'EnvelopeBase');
  const channelValues = channels(document);
  const eventValues = serverEventTypes(document);

  return [
    ...BANNER,
    `export const WS_SPEC_VERSION = ${literal(String(document.info.version))} as const;`,
    `export const WS_SPEC_SHA256 = ${literal(sha256)} as const;`,
    `export const WS_ENDPOINT = ${literal(address)} as const;`,
    `export const WS_PROTOCOL_VERSION = ${literal(protocolVersion)} as const;`,
    `export const EVENT_CHANNELS: readonly EventChannel[] = [${channelValues.map(literal).join(', ')}];`,
    `export type EventChannel = ${channelValues.map(literal).join(' | ')};`,
    `export const SERVER_EVENT_TYPES: readonly ServerEventType[] = [${eventValues.map(literal).join(', ')}];`,
    `export type ServerEventType = ${eventValues.map(literal).join(' | ')};`,
    'export const CONTROL_MESSAGE_TYPES = ["subscribe", "unsubscribe", "ping"] as const;',
    'export type ControlMessageType = (typeof CONTROL_MESSAGE_TYPES)[number];',
    '',
  ].join('\n');
}

function main(argv) {
  const [specArgument, outputArgument, ...rest] = argv;
  if (specArgument === undefined || outputArgument === undefined || rest.length > 1) {
    fail('usage: generate-web-events.cjs <asyncapi.yaml> <output.ts> [--check]');
  }
  const checkMode = rest[0] === '--check';
  if (rest.length === 1 && !checkMode) {
    fail(`unknown argument: ${rest[0]}`);
  }

  const specPath = path.resolve(process.cwd(), specArgument);
  const outputPath = path.resolve(process.cwd(), outputArgument);
  const generated = generate(specPath);

  if (checkMode) {
    if (!fs.existsSync(outputPath)) {
      fail(`generated event constants are missing: ${outputPath}`);
    }
    if (fs.readFileSync(outputPath, 'utf8') !== generated) {
      fail(`generated event constants are stale: ${outputPath}. Run npm run generate:web-client.`);
    }
    console.log(`generated event constants are current: ${path.relative(process.cwd(), outputPath)}`);
    return;
  }

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, generated, 'utf8');
  console.log(`wrote generated event constants: ${path.relative(process.cwd(), outputPath)}`);
}

if (require.main === module) {
  try {
    main(process.argv.slice(2));
  } catch (error) {
    console.error(`generate-web-events: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  }
}

module.exports = { generate, readSpec };
